	public static AnimationDefinition of(LoversAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case ATTACK -> ATTACK;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in LoversAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(LoversAnim.values()).map(LoversAnimations::of).toList();
	}
